import json,hashlib
p='/workspace/recovery/agent319/artifacts/batch369-378.json'
d={'pages':[],'units':[],'boundary_notes':[],'review_notes':[]}
def add(n,ar,ru,complete=True,join=False):
 if not d['pages'] or d['pages'][-1]['printed_page']!=n:d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=[]))
 pg=d['pages'][-1];sid=f'v4-p{n:03}-{len(pg["paragraphs"])+1:02}'
 pg['paragraphs'].append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=complete))
 if join:
  u=d['units'][-1];u['source_ids'].append(sid);u['printed_pages'].append(n);u['ar']+=' '+ar;u['ru']+=' '+ru
 else:d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
add(369,'عقاب ولا انتقام. وهذا تلبيس عليهم، فإنّ هذه الأمور إنّما أوجبها محض مشيئة الله، الذي ما شاء كان، وما لم يشأ لم يكن، فانطوى حكم تلك الوسائط والأسباب والعلل في بساط المشيئة الأزليّة، واضمحلّت في عين الحكم الأزليّ، وصارت من جملة الكائنات التي هي منفعلة لا فاعلة، ومطيعة لا مطاعة، ومأمورة لا آمرة، وخلق من خلقه، لا واسطة منه وبين خلقه، فهي به لا بهم. ولهذا عاد العارفون به منه، وهربوا منه إليه، والتجأوا منه إليه، وفرّوا منه إليه، وتوكّلوا به عليه، وخافوا بما منه لا من غيره. فشهدوا أوّليّته في كلّ شيء، وتفرّده في الصنع، وأنّه ما ثمّ ما يوجب شيئًا من الأشياء إلّا مشيئته وحده، فمشيئته هي السبب في الحقيقة، وما يشاهد ويعلم من الأسباب فمحلّ ومجرى لنفوذ المشيئة، لا أنّه مؤثّر وفاعل. فالوسائط لا بدّ أن تنتهي إلى أوّل، لامتناع التسلسل، ولهذا قال النبيّ ﷺ: «فمن أعدى الأوّل؟».','наказания, ни возмездия. Это тальбис по отношению к ним: ведь всё перечисленное обусловлено одной лишь волей Аллаха — что Он пожелал, то произошло, а чего не пожелал, того не было. Поэтому действие этих промежуточных причин, причин и оснований сворачивается на ковре предвечной воли, исчезает в самом предвечном решении и оказывается среди сотворённых вещей, которые принимают воздействие, а не действуют, повинуются, а не подчиняют, исполняют повеления, а не повелевают. Это часть Его творения, а не посредник между Ним и Его творением: они существуют благодаря Ему, а не благодаря им. Поэтому познавшие Его возвращаются от Него к Нему, бегут от Него к Нему, ищут у Него убежища от Него, спасаются от Него у Него, благодаря Ему уповают на Него и боятся того, что исходит от Него, а не от другого. Они созерцают Его первенство во всём, Его единоличное творение и то, что ничто не обусловливает никаких вещей, кроме одной Его воли. Его воля и есть причина в действительности, а видимые и известные причины — лишь место и русло осуществления этой воли, а не то, что само влияет и действует. Промежуточные причины неизбежно восходят к первой, поскольку бесконечная цепь невозможна. Потому Пророк ﷺ и сказал: «Кто же заразил первого?»',False)
add(369,'والله سبحانه قدّر المقادير، وكتب الآثار والأعمال، والشقاوة والسعادة، والثواب والعقاب، حيث لا واسطة هناك ولا سبب ولا علّة، فأهل التفرقة وقفوا مع الوسائط، وأهل الجمع نفذ بصرهم من الوسائط والأسباب إلى من أقامها وربط بها أحكامها.','Аллах — пречист Он! — предопределил судьбы и записал следы и деяния, несчастье и счастье, награду и наказание, когда ещё не было ни промежуточной причины, ни причины, ни основания. Люди раздельного видения остановились на промежуточных причинах, а взор людей собранности проник сквозь промежуточные причины и причины к Тому, Кто установил их и связал с ними их следствия.')
add(369,'قوله: (وأخفى الرضا والسخط اللّذين يوجبان الوصل والفصل)، يعني: أنّه سبحانه أخفى عن عباده ما سبق لهم عنده من سخطه عمّن سخط عليه،','Его слова: «И сокрыл довольство и гнев, которые обусловливают соединение и разлучение». Он имеет в виду, что Он, пречистый, сокрыл от Своих рабов то, что заранее определено им у Него: Свой гнев на тех, на кого Он разгневался,',False)
add(370,'ورضاه عمّن رضي عنه الموجبين لوصل من وصله، وقطع من قطعه.','и Своё довольство теми, кем Он доволен, — то, что обусловливает соединение с теми, кого Он соединил, и отсечение тех, кого Он отсёк.',False,True)
add(370,'ومراده: أنّ هذا هو السبب الصحيح في نفس الأمر، وهو رضاه وسخطه، وإنّما لبّس سبحانه على أهل التفرقة الأمر بما ذكره من الجنايات والطاعات، والعلل والحجج، ولا سبب في الحقيقة إلّا رضاه وسخطه، وذلك لا علّة له، فالرضا هو الذي أوجب المثوبة لا الطاعة، والسخط هو الذي أوجب العقوبة لا المعصية، والمشيئة هي التي أوجبت الحكم لا الوسائط، فأخفى الربّ سبحانه ذلك عن خلقه، وأظهر لهم أسبابًا أخر علّقوا بها الأحكام، وذلك تلبيس من الحقّ عليهم. فأهل التفرقة وقفوا مع هذا التلبيس، وأهل الجمع صعدوا عنه، وجاوزوه إلى مصدر الأشياء كلّها وموجدها بمشيئته فقط.','Он имеет в виду, что именно это — подлинная причина на самом деле: Его довольство и гнев. А Он, пречистый, лишь ввёл людей раздельного видения в заблуждение относительно происходящего посредством названных преступлений и послушания, оснований и доводов. В действительности же нет причины, кроме Его довольства и гнева, а у них нет основания. Награду обусловило довольство, а не послушание; наказание обусловил гнев, а не ослушание; решение обусловила воля, а не промежуточные причины. Господь, пречистый, сокрыл это от Своего творения и явил ему другие причины, с которыми люди связали решения. Это и есть, по его словам, тальбис со стороны Истинного по отношению к ним. Люди раздельного видения остановились на этом тальбисе, а люди собранности поднялись над ним и прошли за него к источнику всех вещей и Тому, Кто даёт им существование одной лишь Своей волей.')
add(370,'وبالغ الشيخ في ذلك حتّى جعل الرضا والسخط يُظهران السعادة والشقاوة، ولم يجعل الرضا والسخط مؤثّرين فيهما، وذلك لأنّ السعادة والشقاوة سبقت عنده سبقًا محضًا مستندًا إلى محض المشيئة لا علّة لهما، والرضا والسخط أظهرا ما سبق به التقدير من السعادة والشقاوة. فهذا أحسن ما يقال في شرح كلامه وتقريره وحمله على أحسن الوجوه وأجملها.','Шейх дошёл в этом до того, что сделал довольство и гнев лишь обнаруживающими счастье и несчастье, а не влияющими на них. Ведь, по его мнению, счастье и несчастье были заранее определены исключительно одной волей, без всякого основания, а довольство и гнев лишь обнаружили то счастье и несчастье, которые были прежде предопределены. Таково наилучшее объяснение его слов, их раскрытие и толкование в самом благоприятном и достойном смысле.')
add(370,'فأمّا ما فيه من التوحيد وانتهاء الأمور إلى مشيئة الربّ جلّ جلاله، وأنّه ما شاء كان، وما لم يشأ لم يكن= فذلك عقد نظام الإيمان، ومع ذلك فلا يكفي وحده، إذ غايته تحقيق توحيد الربوبيّة الذي لم يكن ينكره عبّاد الأصنام.','Что касается содержащегося здесь единобожия, сведения всего к воле Господа — величественна Его слава! — и признания, что происходит то, чего Он пожелал, а чего не пожелал, того не происходит, — это узел, скрепляющий строй веры. Однако одного этого недостаточно: самое большее, к чему это приводит, — утверждение единобожия господства, которого не отрицали и поклонявшиеся идолам.')
add(371,'وإنّما الشأن في أمر آخر وراءه؛ هذا بابه، والمدخل إليه، والدليل عليه، ومنه يوصل إليه، وهو التوحيد الذي دعت إليه الرسل، ونزلت به الكتب، وعليه الثواب والعقاب، والشرائع كلّها تفاصيله وحقوقه، وهو توحيد الإلهيّة والعبادة، وهو الذي لا سعادة للنفوس إلّا بالقيام به علمًا وعملًا وحالًا، وهو أن يكون الله وحده أحبّ إلى العبد من كلّ ما سواه، وأخوف عنده من كلّ ما سواه، وأرجى له من كلّ ما سواه، فيعبده بمعاني الحبّ والخوف والرجاء بما يحبّه هو ويرضاه، وهو ما شرعه على لسان رسوله ﷺ، لا بما يريده العبد ويهواه، وتلخيص ذلك في كلمتين «إيّاك أريد بما تريد»، فالأولى: توحيد وإخلاص، والثانية: اتّباع للسنّة وتحكيم للأمر.','Всё дело в другом, находящемся за этим: это лишь его дверь, вход к нему и указание на него; через это к нему приходят. Это единобожие, к которому призывали посланники, с которым ниспосылались Писания, за которое даются награда и наказание; все установления Закона — его подробности и права. Это единобожие божественности и поклонения. Души обретают счастье, лишь осуществляя его в знании, делах и состоянии. Оно состоит в том, чтобы один Аллах был рабу любимее всего остального, внушал больший страх, чем всё остальное, и был предметом большей надежды, чем всё остальное; чтобы раб поклонялся Ему с любовью, страхом и надеждой посредством того, что любит и чем доволен Он Сам, то есть того, что Он узаконил устами Своего Посланника ﷺ, а не посредством того, чего хочет и желает сам раб. Всё это выражают две фразы: «К Тебе стремлюсь — посредством того, чего Ты желаешь». Первая — единобожие и искренность, вторая — следование Сунне и признание повеления судьёй.')
add(371,'والمقصود: أنّ ما أشار إليه في هذا الباب غايته تقرير توحيد الأفعال، وهو توحيد الربوبيّة.','Смысл в том, что наибольшее, к чему приводит указанное им в этой главе, — утверждение единства действий, то есть единобожия господства.')
add(371,'وأمّا جعله ما نصبه سبحانه من الأسباب في خلقه وأمره وأحكامه وثوابه وعقابه تلبيسًا، فتلبيس من النفس عليه، وليس ذلك ـ عند العارفين بالله ورسله وأسمائه وصفاته ـ من التلبيس في شيء، وإنّما ذلك مظهر أسمائه وصفاته، وحكمته، ونعمته، وقدرته وعزّته، إذ ظهور هذه الصفات والأسماء يستلزم محالّ ومتعلّقات تتعلّق بها، وتظهر فيها آثارها، هذا أمر ضروريّ للصفات والأسماء، إذ العلم لا بدّ له من معلوم، وصفة الخالقيّة والرازقيّة تستلزم وجود مخلوق ومرزوق، وكذلك صفة الرحمة والإحسان والحلم','Что же касается того, что установленные Им, пречистым, причины в творении, повелении, решениях, награде и наказании он называет тальбисом, то это его собственная душа вводит его в заблуждение. Для познавших Аллаха, Его посланников, Его имена и качества здесь вовсе нет тальбиса. Всё это — проявление Его имён и качеств, мудрости, милости, могущества и величия. Ведь проявление этих качеств и имён предполагает наличие тех, в ком они проявляются, и предметов, к которым они относятся и в которых обнаруживаются их следы. Это необходимо для качеств и имён: знание непременно предполагает познаваемое, качества творения и наделения уделом — существование сотворённого и наделённого уделом. Так же и качества милосердия, благодеяния, выдержки,',False)
d['boundary_notes'].append({'source_id':'v4-p369-01','boundary':'starts_mid_paragraph_from_368','note':'368 ends «ولا»،369 starts «عقاب ولا انتقام»; join Arabic and Russian to prior368 unit. All initial account of causal denial belongs to explanation of al-Harawi, followed by author criticism370ff.'})
open(p,'w').write(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
add(372,'والعفو والمغفرة والتجاوز تستلزم محالّ تتعلّق بها، وتظهر فيها آثارها، فالأسباب والوسائط مظاهر الخلق والأمر، فكيف يكون تعليق الأحكام والثواب والعقاب بها تلبيسًا؟ وهل ذلك إلّا حكمة بالغة، وآيات ظاهرة، وشواهد ناطقة بربوبيّة منشئها وكماله وثبوت أسمائه وصفاته؟ فإنّ الكون كما هو محلّ الخلق والأمر، ومظهر الأسماء والصفات، فهو بجميع ما فيه شواهد وأدلّة وآيات، دعا الله سبحانه عباده إلى النظر فيها، والاستدلال بها على وجود الخالق، والاعتبار بما تضمّنته من الحكم والمصالح والمنافع على علمه وحكمته ورحمته وإحسانه، وبما تضمّنته من العقوبات على عدله، وأنّه يغضب ويسخط ويكره ويمقت، وبما تضمّنته من المثوبات والإكرام على أنّه يحبّ ويرضى ويفرح. فالكون بجملة ما فيه آيات وشواهد وأدلّة، لم يخلق منها شيئًا تلبيسًا، لا وسّطه عبثًا، ولا خلقه سُدًى.','прощения, отпущения и снисхождения предполагают тех, к кому они относятся и в ком проявляются их следы. Причины и промежуточные причины — проявления творения и повеления. Как же связь с ними решений, награды и наказания может быть тальбисом? Разве это не совершенная мудрость, явные знамения и свидетельства, говорящие о господстве их Создателя, Его совершенстве и утверждённости Его имён и качеств? Мир служит вместилищем творения и повеления и проявлением имён и качеств; всё в нём — свидетельства, доказательства и знамения. Аллах — пречист Он! — призвал Своих рабов рассматривать их, выводить из них существование Творца, судить по содержащимся в них мудрости, благим целям и пользе о Его знании, мудрости, милосердии и благодеянии, по содержащимся в них наказаниям — о Его справедливости и о том, что Он гневается, негодует, ненавидит и испытывает отвращение, а по содержащимся в них наградам и почестям — о том, что Он любит, доволен и радуется. Весь мир со всем, что в нём, — знамения, свидетельства и доказательства. Ничто из этого Он не создал ради тальбиса, не сделал промежуточным звеном напрасно и не сотворил бесцельно.',False,True)
add(372,'فالأسباب والوسائط والعلل محلّ أفكار المتفكّرين، واعتبار الناظرين، ومعارف المستدلّين، {إِنَّ فِي ذَلِكَ لَآيَاتٍ لِلْمُتَوَسِّمِينَ} [الحجر: 75]. وكم في القرآن من الحثّ على النظر فيها، والاعتبار بها، والتفكّر فيها، وذمّ من أعرض عنها، والإخبار بأنّ النظر فيها والاستدلال يوجب العلم والمعرفة بصدق رسله؛ فهي آيات كونيّة مشاهدة تصدّق الآيات القرآنيّة.','Причины, промежуточные причины и основания — предмет размышлений размышляющих, извлечения уроков рассматривающих и познания выводящих доказательства. {إِنَّ فِي ذَلِكَ لَآيَاتٍ لِلْمُتَوَسِّمِينَ} — «Воистину, в этом знамения для проницательных» [«Аль-Хиджр», 15:75]. Как часто Коран побуждает рассматривать их, извлекать из них уроки и размышлять о них, порицает отворачивающихся от них и сообщает, что их рассмотрение и вывод доказательств дают знание и познание правдивости Его посланников! Это зримые знамения мироздания, подтверждающие коранические аяты.')
add(372,'فما علّق بها آثارها سُدًى، ولا رتّب عليها مقتضياتها وأحكامها باطلًا، ولا جعل توسيطها تلبيسًا البتّة، بل ذلك موجب كماله وكمال نعوته','Он связал с ними их следствия не бесцельно и установил вытекающие из них результаты и решения не понапрасну, а их промежуточную роль вовсе не сделал тальбисом. Напротив, этого требуют Его совершенство и совершенство Его признаков',False)
add(373,'وصفاته، وبها عُرفت ربوبيّته وإلهيّته وملكه وصفاته وأسماؤه.','и качеств; посредством них познаются Его господство, божественность, владычество, качества и имена.',False,True)
add(373,'هذا، ولم يخلقها سبحانه حاجة منه إليها، ولا توقّفًا لكماله المقدّس عليها، فلم يتكثّر بها من قلّة، ولم يتعزّز بها من ذلّة، بل اقتضى كماله أن يفعل ما يشاء بما يشاء، ويأمر ويتصرّف ويدبّر كما يشاء، وأن يحمد ويعرف، ويذكر ويعبد، ويعرّف الخلق صفات كماله ونعوت جلاله، ولذلك خلق خلقًا يعصونه ويخالفون أمره، ليعرّف ملائكته وأنبياءه ورسله وأولياءه كمال مغفرته وعفوه، وحلمه وإمهاله، ثمّ أقبل بقلوب من شاء منهم إليه، فظهر كرمه في قبول توبته، وبرّه ولطفه في العود عليه بعد الإعراض عنه، كما قال النبيّ ﷺ: «لو لم تذنبوا لذهب الله بكم، ولجاء بقوم يذنبون ثمّ يستغفرون فيغفر لهم». فلمن كانت تكون مغفرته لو لم يخلق الأسباب التي يغفر عنها وبها؟ والعبد الذي له يغفر؟ فخلق العبد المغفور له، وتقدير الذنب الذي يغفر، والتوبة التي يغفر بها= هو نفس مقتضى العزّة والحكمة، وموجب الأسماء الحسنى والصفات العلا، ليس من التلبيس في شيء، فتعليق الكوائن بالأسباب كتعليق الثواب والعقاب بالأسباب، ولهذا سوّى صاحب «المنازل» بين الأمرين، وهو محض الحكمة، وموجب الكمال الإلهيّ، ومقتضى الحمد التامّ، ومظهر صفة العزّة والقدرة والملك. والشرائع كلّها ـ من أوّلها إلى آخرها ـ مبنيّة على تعليق الأحكام بالعلل، والقضايا بالحجج، والثواب بالطاعة، والعقوبات بالجرائم، فهل يقال: إنّ','При этом Он, пречистый, создал их не потому, что нуждался в них, и не потому, что Его святое совершенство от них зависело. Он не умножил ими Свою малочисленность и не укрепился ими от униженности. Напротив, Его совершенство требовало, чтобы Он делал что пожелает посредством чего пожелает, повелевал, распоряжался и управлял как пожелает, чтобы Его восхваляли, познавали, поминали и поклонялись Ему и чтобы Он знакомил творение с качествами Своего совершенства и признаками Своего величия. Потому Он создал существ, которые ослушиваются Его и противятся Его повелению: чтобы открыть Своим ангелам, пророкам, посланникам и приближённым совершенство Своего отпущения грехов, прощения, выдержки и отсрочки. Затем Он обратил к Себе сердца тех из них, кого пожелал, и проявилось Его великодушие в принятии покаяния человека, Его доброта и мягкость — в возвращении к нему после того, как тот отвернулся от Него. Как сказал Пророк ﷺ: «Если бы вы не грешили, Аллах убрал бы вас и привёл людей, которые грешат, затем просят прощения, и Он прощает их». К кому же относилось бы Его прощение, если бы Он не создал причины, за которые прощает и посредством которых прощает, и раба, которого прощает? Создание прощаемого раба, предопределение греха, который прощается, и покаяния, посредством которого прощается, — это и есть то, чего требуют величие и мудрость, чего требуют прекрасные имена и высочайшие качества; здесь вовсе нет тальбиса. Связь происходящего с причинами подобна связи награды и наказания с причинами; поэтому автор «Маназил ас-саирин» и поставил обе вещи в один ряд. Это чистая мудрость, требование божественного совершенства и совершенной хвалы, проявление величия, могущества и владычества. Все установления Закона, от начала до конца, основаны на связи решений с основаниями, судебных дел — с доказательствами, награды — с послушанием, а наказаний — с преступлениями. Неужели можно сказать, что',False)
add(374,'الشرائع كلّها تلبيس، بأيّ معنى فسّر التلبيس؟','все установления Закона — тальбис, какой бы смысл ни придавали этому слову?',False,True)
add(374,'ولعمر الله لقد كان في غنية عن هذا الباب وعن هذه التسمية، ولقد أفسد الكتاب بذلك.','Клянусь жизнью Аллаха, он вполне мог обойтись без этой главы и без этого названия: этим он испортил книгу.')
add(374,'هذا، ولا يجهل محلّ الرجل من العلم والسنّة، وطريق السلوك وآفاته وعلله، ولكن قصده تجريد توحيد الأفعال والربوبيّة قاده إلى ذلك، وانضمّ إليه اعتقاده أنّ الفناء في هذا التوحيد هو غاية السلوك ونهاية العارفين، وساعده اعتقاد كثير من المنتسبين إلى السنّة، الرادّين على القدريّة في الأسباب: أنّها لا تأثير لها البتّة، ولا فيها قوى، ولا يفعل الله شيئًا بشيء ولا شيئًا لشيء، فينكرون أن يكون في أفعاله باء تسبيب أو لام تعليل، وما جاء من ذلك حملوا الباء فيه على المصاحبة، واللام فيه على لام العاقبة، وقالوا: يفعل الله الإحراق والإغراق والإزهاق عند ملاقاة النار والماء والحديد، لا بها ولا بقوى فيها، ولا فرق ـ في نفس الأمر ـ بينها وبين الهواء والتراب والخشب، وانضمّ إلى ذلك أنّ العبد ليس بفاعل أصلًا، وإنّما هو منفعل محض، ومحلّ لجريان تصاريف الأحكام عليه، وأنّ الفاعل فيه سواه، المحرّك له غيره، وإذا قيل: إنّه فاعل أو متحرّك فهو تلبيس.','При этом положение этого человека в знании, Сунне, познании духовного пути, его бедствий и изъянов известно. Однако стремление очистить единобожие действий и господства привело его к этому. К нему добавилось убеждение, что фана в этом единобожии — вершина пути и предел познающих. Его поддержало и убеждение многих относящих себя к Сунне и возражающих кадаритам относительно причин: будто причины вовсе не влияют, не содержат никаких сил и Аллах не совершает ничего посредством чего-либо и ради чего-либо. Они отрицают, что в описании Его действий буква «ба» может выражать причинность, а «лям» — цель. В тех местах, где это встречается, они истолковывают «ба» как совместность, а «лям» — как последствие. Они говорят: Аллах создаёт сгорание, утопление и лишение жизни при соприкосновении с огнём, водой и железом, а не посредством них или заключённых в них сил; на самом деле между ними и воздухом, землёй и деревом нет различия. К этому добавилось утверждение, что раб вовсе не действует, а лишь подвергается воздействию и служит местом осуществления различных решений над ним; действующий в нём — другой, движущий его — иной. А если говорится, что раб действует или движется, то это тальбис.')
add(374,'فهذه الأصول أوجبت هذا التلبيس على نفاة الحكم والأسباب، وقابلهم آخرون فمزّقوا لحومهم كلّ ممزّق، وفرّوا أديمهم، وقالوا: عطّلتم الشرائع والثواب والعقاب، وأبطلتم حقيقة الأمر والنهي، فإنّ','Эти исходные положения обусловили такой тальбис для отрицающих мудрые цели и причины. Им противостали другие, которые разорвали их плоть в клочья, рассекли их кожу и сказали: «Вы упразднили установления Закона, награду и наказание и уничтожили саму действительность повеления и запрета. Ведь',False)
