for u in d['units']:
 u['ru']=u['ru'].replace('сворачивается на ковре предвечной воли, исчезает в самом предвечном решении и оказывается среди сотворённых вещей','сворачивается на ковре предвечной воли; сами они исчезают в самом предвечном решении и становятся частью сотворённых вещей').replace('Именно их сподвижники, их последователи и имамы ислама единодушно порицали, считали приверженцами нововведений и заблудшими.','Именно их единодушно порицали сподвижники, последователи сподвижников и имамы ислама, считая приверженцами нововведений и заблудшими.').replace('они заблудшее скота','они ещё более заблудшие, чем скот').replace('Причины, промежуточные причины и основания — предмет размышлений размышляющих, извлечения уроков рассматривающих и познания выводящих доказательства.','Причины, промежуточные причины и основания служат предметом размышления для мыслящих, источником уроков для всматривающихся и познания для выводящих доказательства.')
d['review_notes'].append({'pass':'russian_only','performed':True,'scope':'Read all29 joined Russian units in order independently of Arabic syntax, including boundary fragment369.','issues_found':['369 Russian incorrectly kept действие as grammatical subject when Arabic returns to the causes themselves.','376 Russian possessive ambiguity could make сподвижники appear to belong to the Qadarites.','376 comparative заблудшее скота and372 introductory parallel phrase were awkward.'],'resolution':'Restated369 clause subject explicitly; moved object их before predicate and used последователи сподвижников; improved comparative and parallel Russian wording without shortening author argument.'})
